from pathlib import Path
D=Path(__file__).resolve().parents[1]
RUNTIME_FILES=('stage5_common.py','stage5_cloud_worker.py','stage5_kimi_gateway.py','stage5_kimi_worker.py','stage5_prepare.py','stage5_validate_kimi.py')
def install_prepare(control,base):
 v=D/'runtime_direct_v3';sources={name:(v/name).read_bytes() for name in RUNTIME_FILES}
 for name,raw in sources.items():compile(raw,name,'exec')
 bundle={name:{'compressed':base64.b64encode(zlib.compress(raw,9)).decode(),'sha256':hashlib.sha256(raw).hexdigest()} for name,raw in sources.items()}
 source=base+'\nBUNDLE='+repr(bundle)+'''\nimport base64,zlib\nos.umask(0o077);V=C/'runtime_direct_v3';K=C/'kimi_direct_v3';T=C/'kimi_direct_transition_v3'\nV.mkdir(exist_ok=True)\nfor name,entry in BUNDLE.items():\n raw=zlib.decompress(base64.b64decode(entry['compressed']));assert hashlib.sha256(raw).hexdigest()==entry['sha256'];p=V/name\n if p.exists():assert p.read_bytes()==raw,'immutable_direct_runtime_conflict'\n else:p.write_bytes(raw)\nassert not (K/'ADMISSION_PRIVATE.sqlite3').exists(),'direct_ledger_exists_do_not_reprepare'\nrepo=C/'repo';fv=repo/'linkup/reuse_first_20261115/measurement_protocol_20261117/code/field_validation.py';ov=repo/'linkup/formal800_20261012/code/validate_reviews.py';L=C/'luna'\ncmd=[sys.executable,'-B',str(V/'stage5_prepare.py'),'--leg','Kimi','--directory',str(K),'--inputs',str(D/'fresh_inputs_v1/INPUTS_PRIVATE.jsonl'),'--roster',str(C/'FRAME_PRIVATE.jsonl'),'--schema',str(L/'SCHEMA.json'),'--instructions',str(L/'INSTRUCTIONS.md'),'--exclusions',str(D/'fresh_inputs_v1/EXCLUSIONS_PRIVATE.json'),'--field-validator',str(fv),'--frozen-validator',str(ov),'--predecessor-receipt',str(L/'LUNA_FINAL_PUBLIC.json'),'--predecessor-exclusions',str(L/'EXCLUSIONS_EXPORT_PRIVATE.json')]\ncp=subprocess.run(cmd,capture_output=True,text=True,timeout=120)\n(C/'DIRECT_PREPARE_EXECUTION_PRIVATE.json').write_text(json.dumps({'returncode':cp.returncode,'stdout':cp.stdout,'stderr':cp.stderr}))\nassert cp.returncode==0,'direct_offline_prepare_failed_details_private'\ncmd=[sys.executable,'-B',str(V/'stage5_kimi_worker.py'),'--directory',str(K),'--import-prior-only','--prior-directory',str(T/'prior'),'--prior-closure',str(T/'KIMI_V2_CLOSURE_PUBLIC.json')]\ncp=subprocess.run(cmd,capture_output=True,text=True,timeout=120)\n(C/'DIRECT_PRIOR_IMPORT_EXECUTION_PRIVATE.json').write_text(json.dumps({'returncode':cp.returncode,'stdout':cp.stdout,'stderr':cp.stderr}))\nassert cp.returncode==0,'direct_prior_import_failed_details_private'\nr=json.loads(cp.stdout);r.update(status='direct_runtime_prepared_prior_imported_no_new_calls',runtime_files_sha256={n:x['sha256'] for n,x in BUNDLE.items()},directory=str(K))\n(C/'DIRECT_PREPARE_PUBLIC.json').write_text(json.dumps(r,sort_keys=True)+'\\n');print(json.dumps(r))\n'''
 compile(source,'<install-direct-runtime>','exec');r=control.vm(source,'stage5_prepare_direct_'+str(time.time_ns()))
 control.save(D/'control/DIRECT_PREPARE_PUBLIC.json',r);print(json.dumps(r))
def launch(control,base):
 source=base+'''\nos.umask(0o077);K=C/'kimi_direct_v3';V=C/'runtime_direct_v3';receipt=C/'DIRECT_LAUNCH_PUBLIC.json'\nassert not receipt.exists(),'direct_prior_launch_no_duplicate'\nassert not (K/'KIMI_FINAL_PUBLIC.json').exists(),'direct_prior_final_no_duplicate'\nsys.path.insert(0,str(V));from stage5_common import load_inputs\nitems,pins=load_inputs(K,'Kimi');p=read(C/'DIRECT_PREPARE_PUBLIC.json');assert p['status']=='direct_runtime_prepared_prior_imported_no_new_calls'\ncmd=[sys.executable,'-B',str(V/'stage5_kimi_worker.py'),'--directory',str(K),'--execute','--workflow-directory',str(R/'code'),'--max-wall-seconds','14400']\nwith (K/'WORKER_PRIVATE.log').open('ab') as log:worker=subprocess.Popen(cmd,stdin=subprocess.DEVNULL,stdout=log,stderr=log,start_new_session=True)\nr={'status':'direct_Azure_Kimi_worker_launched_not_completion','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pid':worker.pid,'directory':str(K),'identity_type':'existing_VM_managed_identity','selected':len(items),'prior_reused_provider_calls':10,'remaining_at_launch':125,'Kimi_cap_usd_including_prior':40,'all_legs_cap_usd':50,'TPM_response_verified':3000000,'TPM_scheduled':240000,'max_wall_seconds':14400,'OpenCode_used':False}\nreceipt.write_text(json.dumps(r,sort_keys=True)+'\\n');print(json.dumps(r))\n'''
 r=control.vm(source,'stage5_launch_direct_'+str(time.time_ns()));control.save(D/'control/DIRECT_LAUNCH_PUBLIC.json',r);print(json.dumps(r))
def status(control,base):
 source=base+'''\nK=C/'kimi_direct_v3';L=C/'DIRECT_LAUNCH_PUBLIC.json';la=read(L) if L.exists() else {};pid=la.get('pid')\np=Path('/proc')/str(pid)/'cmdline'\nr={'status':'direct_Kimi_snapshot','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pid':pid,'process_active':bool(pid and p.exists() and b'runtime_direct_v3/stage5_kimi_worker.py' in p.read_bytes())}\nfor name in ('RUN_STATUS_PUBLIC.json','KIMI_FINAL_PUBLIC.json'):\n p=K/name\n if p.exists():r[name]=read(p)\np=K/'ADMISSION_PRIVATE.sqlite3'\nif p.exists():\n db=sqlite3.connect(p.as_uri()+'?mode=ro',uri=True)\n r['attempt_states']=dict(db.execute('select state,count(*) from attempts group by state'));r['physical_attempts']=db.execute('select count(*) from attempts').fetchone()[0];r['reserved_usd']=db.execute('select coalesce(sum(dollars_nano),0)/1e9 from attempts').fetchone()[0]\n details=[json.loads(x[0]) for x in db.execute('select detail from attempts')]\n r['input_tokens']=sum(x.get('usage',{}).get('prompt_tokens',0) for x in details);r['output_tokens']=sum(x.get('usage',{}).get('completion_tokens',0) for x in details)\n r['rate_limit_tokens_headers']=sorted({str(x.get('rate_headers',{}).get('x-ratelimit-limit-tokens')) for x in details if x.get('rate_headers')})\n r['http_status_counts']={str(code):sum(x.get('http_status')==code for x in details) for code in sorted({x['http_status'] for x in details if 'http_status' in x})}\n db.close()\nif not r['process_active'] and not (K/'KIMI_FINAL_PUBLIC.json').exists():\n p=K/'WORKER_PRIVATE.log'\n if p.exists():\n  for line in p.read_text().splitlines():\n   try:\n    x=json.loads(line)\n    if 'fatal_error_type' in x:r['fatal_error_type']=x['fatal_error_type']\n   except ValueError:pass\nprint(json.dumps(r))\n'''
 r=control.vm(source,'stage5_status_direct_'+str(time.time_ns()));control.save(D/'control'/('DIRECT_STATUS_'+str(time.time_ns())+'_PUBLIC.json'),r)
 if 'KIMI_FINAL_PUBLIC.json' in r:control.save(D/'KIMI_FINAL_PUBLIC.json',r['KIMI_FINAL_PUBLIC.json'])
 print(json.dumps(r))
