 source=base+'\nTRANSITION='+repr(t)+'''\nimport io,zipfile\nos.umask(0o077);T=C/'kimi_direct_transition_v3'\nsys.path.insert(0,str(R/'code'));from workflow import call\nurl='https://stlinkup70d455c0261104.blob.core.windows.net/astra-handoff/'+TRANSITION['blob_key']\nwith call(url,'https://storage.azure.com/',headers={'x-ms-version':'2023-11-03'}) as response:b=response.read(50000001)\nassert len(b)==TRANSITION['bytes'] and hashlib.sha256(b).hexdigest()==TRANSITION['sha256']\nz=zipfile.ZipFile(io.BytesIO(b));closure=json.loads(z.read('KIMI_V2_CLOSURE_PUBLIC.json'));pins=closure['prior_files_sha256']\nassert hashlib.sha256(z.read('KIMI_V2_CLOSURE_PUBLIC.json')).hexdigest()==TRANSITION['closure_sha256']\nassert set(z.namelist())=={'prior/'+n for n in pins}|{'KIMI_V2_CLOSURE_PUBLIC.json'}\nassert sum(i.file_size for i in z.infolist())<50000000\nfor n in z.namelist():\n assert not Path(n).is_absolute() and '..' not in Path(n).parts and 'opencode.json' not in n\n raw=z.read(n)\n if n.startswith('prior/'):assert hashlib.sha256(raw).hexdigest()==pins[n[6:]]\n p=T/n;p.parent.mkdir(parents=True,exist_ok=True)\n if p.exists():assert p.read_bytes()==raw,'immutable_direct_transition_conflict'\n else:p.write_bytes(raw)\nr={'status':'direct_transition_imported_SHA_verified','prior_physical_attempts':closure['physical_attempts'],'prior_logical_calls':closure['logical_calls'],'prior_reserved_usd':closure['reserved_nano']/1e9,'verified_response_TPM_headers':closure['verified_response_TPM_headers'],'destination':str(T),'new_model_calls':0}\n(T/'IMPORT_PUBLIC.json').write_text(json.dumps(r,sort_keys=True)+'\\n');print(json.dumps(r))\n'''
 compile(source,'<stage5-direct-transition>','exec')
 r=control.vm(source,'stage5_import_direct_transition_'+str(time.time_ns()));control.save(D/'control/DIRECT_TRANSITION_IMPORT_PUBLIC.json',r);print(json.dumps(r))
